<?php
require_once 'functions.php';require_role(['admin','kasir']);$id=(int)($_GET['id']??0);$trans=null;$details=[];
if($id){$s=$pdo->prepare("SELECT t.*,p.nama_pelanggan FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE t.id_transaksi=?");$s->execute([$id]);$trans=$s->fetch();if($trans){$s=$pdo->prepare("SELECT * FROM tbl_detail_transaksi WHERE id_transaksi=?");$s->execute([$id]);$details=$s->fetchAll();}}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$tid=(int)$_POST['id_transaksi'];$method=$_POST['metode'];$cash=(float)($_POST['uang_diterima']??0);$disc=max(0,(float)($_POST['diskon_tambahan']??0));$s=$pdo->prepare("SELECT * FROM tbl_transaksi WHERE id_transaksi=? FOR UPDATE");$pdo->beginTransaction();try{$s->execute([$tid]);$t=$s->fetch();if(!$t)throw new Exception('Transaksi tidak ditemukan.');$total=max(0,(float)$t['total_bayar']-$disc);$change=$method==='tunai'?max(0,$cash-$total):0;if($method==='tunai' && $cash<$total)throw new Exception('Uang diterima kurang.');$pdo->prepare("INSERT INTO tbl_pembayaran(id_transaksi,metode,jumlah_bayar,uang_diterima,kembalian,status) VALUES(?,?,?,?,?,'berhasil')")->execute([$tid,$method,$total,$cash,$change]);$pdo->prepare("UPDATE tbl_transaksi SET id_user=?,diskon=diskon+?,total_bayar=?,total_belanja=? ,status='selesai' WHERE id_transaksi=?")->execute([user()['id_user'],$disc,$total,$total,$tid]);foreach($details as $d){$st=$pdo->prepare("SELECT stok,jenis_produk FROM tbl_produk WHERE id_produk=? FOR UPDATE");$st->execute([$d['id_produk']]);$p=$st->fetch();if($p && $p['jenis_produk']==='barang'){if((int)$p['stok']<(int)$d['jumlah'])throw new Exception('Stok tidak mencukupi untuk '.$d['nama_produk']);$pdo->prepare("UPDATE tbl_produk SET stok=stok-? WHERE id_produk=?")->execute([$d['jumlah'],$d['id_produk']]);}}$no='STR-'.date('Ymd').'-'.$tid;$pdo->prepare("INSERT INTO tbl_struk(id_transaksi,nomor_struk) VALUES(?,?) ON DUPLICATE KEY UPDATE nomor_struk=VALUES(nomor_struk)")->execute([$tid,$no]);$pdo->commit();log_activity($pdo,'Selesaikan transaksi',$no);go('struk.php?id='.$tid);}catch(Throwable $e){$pdo->rollBack();flash($e->getMessage(),'error');go('kasir_pos.php?id='.$tid);}}
layout_header('Kasir POS');
?>
<div class="page-title"><div><span class="eyebrow">POINT OF SALE</span><h1>Proses pembayaran</h1><p>Pilih pesanan yang akan diselesaikan.</p></div></div>
<?php if(!$trans):?><div class="panel"><h3>Pilih pesanan</h3><p>Masuk ke menu Pesanan Masuk lalu klik Proses, atau pilih nomor transaksi.</p><a class="btn btn-primary" href="kasir_pesanan.php">Lihat Pesanan Masuk</a></div><?php else:?><div class="cart-layout"><section class="panel"><span class="tag"><?=e($trans['nomor_transaksi'])?></span><h2><?=e($trans['nama_pelanggan']??'Pelanggan')?></h2><?php foreach($details as $d):?><div class="summary-row"><span><?=e($d['nama_produk'])?> × <?=$d['jumlah']?></span><b><?=rupiah($d['subtotal'])?></b></div><?php endforeach;?></section><aside class="panel"><h3>Rincian pembayaran</h3><div class="summary-row"><span>Subtotal</span><b><?=rupiah($trans['subtotal'])?></b></div><div class="summary-row"><span>Diskon pesanan</span><b><?=rupiah($trans['diskon'])?></b></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id_transaksi" value="<?=$id?>"><label>Diskon tambahan (Rp)</label><input type="number" name="diskon_tambahan" min="0" max="<?=$trans['total_bayar']?>" value="0"><label>Metode pembayaran</label><select name="metode"><option value="tunai">Tunai</option><option value="transfer">Transfer Bank</option><option value="qris">QRIS</option><option value="ewallet">E-Wallet</option><option value="saldo">Saldo</option></select><label>Uang diterima (untuk tunai)</label><input type="number" name="uang_diterima" min="0" value="<?=$trans['total_bayar']?>"><div class="summary-total"><span>Total awal</span><strong><?=rupiah($trans['total_bayar'])?></strong></div><button class="btn btn-primary full" data-confirm="Selesaikan transaksi dan kurangi stok barang?">Selesaikan & Cetak Struk</button></form></aside></div><?php endif;?>
<?php layout_footer(); ?>
